   677  Layer* Packet::createFirstLayer(LinkLayerType linkType)
   678  {
   679          if (linkType == LINKTYPE_ETHERNET)
   680          {
   681                  // In order to distinguish between Ethernet II and IEEE 802.3 Ethernet the common method is
   682                  // to check the length field. In IEEE 802.3 Ethernet the length value should be equal or
   683                  // less than 0x5DC which corresponds to 1500 bytes. If the value is larger than 0x5DC
   684                  // it means the value is an Ether Type which belongs to Ethernet II.
   685                  // You can read more in this link:
   686                  // https://www.ibm.com/support/pages/ethernet-version-2-versus-ieee-8023-ethernet
   687
   688                  size_t rawDataLen = (size_t)m_RawPacket->getRawDataLen();
   689                  const uint8_t* rawData = m_RawPacket->getRawData();
   690                  if (rawDataLen >= sizeof(ether_header))
   691                  {
   692                          uint16_t ethTypeOrLength = be16toh(*(uint16_t*)(rawData + 12));
   693                          if (ethTypeOrLength <= (uint16_t)0x5dc && ethTypeOrLength != 0)
   694                          {
   695                                  return new EthDot3Layer((uint8_t*)rawData, rawDataLen, this);
   696                          }
   697                  }
   698
   699                  return new EthLayer((uint8_t*)rawData, rawDataLen, this);
   700          }
   701          else if (linkType == LINKTYPE_LINUX_SLL)
   702          {
   703                  return new SllLayer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), this);
   704          }
   705          else if (linkType == LINKTYPE_NULL)
   706          {
   707                  return new NullLoopbackLayer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), this);
   708          }
   709          else if (linkType == LINKTYPE_RAW || linkType == LINKTYPE_DLT_RAW1 || linkType == LINKTYPE_DLT_RAW2)
   710          {
   711                  uint8_t ipVer = m_RawPacket->getRawData()[0] & 0xf0;
   712                  if (ipVer == 0x40)
   713                  {
   714                          return new IPv4Layer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), NULL, this);
   715                  }
   716                  else if (ipVer == 0x60)
   717                  {
   718                          return new IPv6Layer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), NULL, this);
   719                  }
   720                  else
   721                  {
   722                          return new PayloadLayer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), NULL, this);
   723                  }
   724          }
   725
   726          // unknown link type
   727          return new EthLayer((uint8_t*)m_RawPacket->getRawData(), m_RawPacket->getRawDataLen(), this);
   728  }
